export default [{"id":"si","word":"死","alternatives":["s","亖","似了","鼠了"],"category":"平台限流","reason":"短视频和社区平台会降低带“死”“死亡”等负面词内容的推荐，博主就用拼音、形近字或谐音代替。","example":"这家火锅辣到我直接似了😭","trivia":"“亖”本是“四”的古写法，因为长得像“死”被借来用。","featuredDate":"2026-10-29"},{"id":"zui","word":"最","alternatives":["蕞","zui","超","巨"],"category":"广告法","reason":"《广告法》第九条禁止“最”“第一”“国家级”等极限用语。带货笔记被认定为商业广告时，用了就会被限流甚至处罚。","example":"这是我今年用过蕞好用的一支口红💄","trivia":"违反极限用语规定最高可罚 100 万元，所以连“最后一天”也常被写成“蕞后一天”。"},{"id":"qian","word":"钱","alternatives":["米","q","💰","马内"],"category":"金钱交易","reason":"笔记里频繁出现“钱”和具体价格，容易被判定为私下交易或营销，降低曝光。","example":"这件外套才两百米，姐妹们冲！","trivia":"“马内”是英文 money 的音译。"},{"id":"weixin","word":"微信","alternatives":["v","vx","绿泡泡","威❤"],"category":"引流/联系方式","reason":"各平台都禁止把用户引到别的平台，出现“微信”二字或微信号会被删帖、限流。","example":"想要同款的姐妹可以戳绿泡泡～","trivia":"“绿泡泡”来自微信绿色的对话气泡图标。"},{"id":"sixin","word":"私信","alternatives":["私","sx","滴滴","戳我"],"category":"引流/联系方式","reason":"“私信我”会被视为引导私下沟通或交易，小红书等平台会降低这类笔记的流量。","example":"想要链接的宝子滴滴我呀","trivia":""},{"id":"zisha","word":"自杀","alternatives":["紫砂","自鲨","zs"],"category":"平台限流","reason":"涉及自杀的内容会被重点审核或屏蔽，正常讨论也常被误伤，网友改用同音的“紫砂”。","example":"这道题错了三遍，我想原地紫砂","trivia":"平台识别到真实的轻生倾向时，通常会弹出心理援助热线。"},{"id":"xue","word":"血","alternatives":["番茄酱","红色液体","xue"],"category":"平台限流","reason":"血腥画面和词汇在短视频平台会被限流或要求打码，影视解说常用“番茄酱”代替。","example":"这部剧番茄酱也用得太多了吧","trivia":"早年的影视剧确实常用番茄酱、糖浆调道具血。"},{"id":"jingcha","word":"警察","alternatives":["蜀黍","jc","阿sir"],"category":"平台限流","reason":"涉及执法部门的内容审核更严，网友用“蜀黍”（叔叔的谐音）等说法降低被审核的概率。","example":"路边遇到蜀黍查酒驾，排了好长的队","trivia":"“阿sir”来自香港警匪片里对警察的称呼。"},{"id":"dubo","word":"赌博","alternatives":["菠菜","bc","du"],"category":"金钱交易","reason":"赌博在中国内地违法，相关词会被直接屏蔽；“菠菜”是“博彩”的谐音。","example":"陌生人拉你进菠菜群千万别信，都是坑","trivia":"博彩的拼音 bo cai，正好和“菠菜”同音。"},{"id":"fanqiang","word":"翻墙","alternatives":["梯子","科学上网","fq","魔法"],"category":"政治审查","reason":"绕过网络封锁访问境外网站的话题在国内平台受严格限制，教程和工具名称都会被删。","example":"出国前记得先准备好梯子，不然谷歌都打不开","trivia":"“墙”指防火长城（Great Firewall，简称 GFW）。"},{"id":"fengcheng","word":"封城","alternatives":["静默","封控","fc"],"category":"政治审查","reason":"2020—2022 年防疫期间，“封城”相关讨论受到管控，官方和网友多用“静默管理”等说法。","example":"小区又静默了，囤的菜还够吃三天","trivia":"“静默”原本是官方通知里的用语，后来成了日常说法。"},{"id":"yiqing","word":"疫情","alternatives":["口罩","yq","大流行"],"category":"政治审查","reason":"疫情期间相关词被大量审核，许多人用“口罩”指代那段时期。","example":"口罩那三年，我学会了自己剪头发","trivia":"“口罩三年”后来成了对 2020—2022 年的常见代称。"},{"id":"yimin","word":"移民","alternatives":["润","run","rùn","跑路"],"category":"政治审查","reason":"2022 年前后，讨论离开中国、移民海外的内容大量出现，相关话题受到限制，网友用“润”（英文 run 的拼音写法）代替。","example":"考完雅思，准备润去澳洲读研了","trivia":"“润”取自 run 与汉语拼音 rùn 字形相同，意为“跑”；“润学”指研究怎么移民的学问。"},{"id":"zhengfu","word":"政府","alternatives":["zf","有关部门","上面"],"category":"政治审查","reason":"带“政府”字样的批评性内容容易被删帖，网友改用拼音缩写或模糊说法。","example":"听说zf又出新补贴了，有人知道怎么申请吗？","trivia":""},{"id":"hesuan","word":"核酸","alternatives":["hs","捅喉咙","做个检测"],"category":"政治审查","reason":"防疫期间对核酸检测、健康码的抱怨内容常被删除，网友改用拼音缩写或口语说法。","example":"那会儿每天出门第一件事就是去捅喉咙","trivia":"“大白”是当时对穿白色防护服的防疫人员的称呼。"},{"id":"yiwan","word":"一万","alternatives":["1w","一个w","1W"],"category":"金钱交易","reason":"具体金额在理财、副业类内容里容易被判定为夸大收益或交易引导，常用“w”表示“万”。","example":"工作三年，终于存下第一个10w！","trivia":"w 是“万”的拼音 wan 的首字母。"},{"id":"jianfei","word":"减肥","alternatives":["jf","减fei","瘦身","掉秤"],"category":"健康医疗","reason":"平台严管减肥产品和“快速瘦”宣传，涉及功效的说法容易被判为违规的医疗或保健宣传。","example":"坚持跳操一个月，终于掉秤5斤🎉","trivia":""},{"id":"yiyuan","word":"医院","alternatives":["yy","医yuan","🏥"],"category":"健康医疗","reason":"发布医疗内容需要资质，提到具体医院和疗效容易被判定为医疗广告。","example":"今天去yy复查，一切正常～","trivia":""},{"id":"tuikuan","word":"退款","alternatives":["tk","退米","退k"],"category":"金钱交易","reason":"“退款”“维权”这类交易纠纷词容易被系统识别为负面或售后内容，降低曝光。","example":"客服说七天内可以tk，放心冲","trivia":""},{"id":"pianzi","word":"骗子","alternatives":["pz","骗纸","片子"],"category":"平台限流","reason":"直接说某人或某店是“骗子”可能被举报为人身攻击、诽谤，网友用谐音避开。","example":"这家店就是骗纸，大家避雷！","trivia":""},{"id":"guanggao","word":"广告","alternatives":["gg","恰饭","推广"],"category":"平台限流","reason":"平台要求商业合作走官方接单渠道，笔记里出现“广告”会被识别为私下接广告而限流。","example":"这期不是恰饭，纯分享自用好物","trivia":"“恰饭”是西南方言的“吃饭”，B 站 UP 主用它指接广告赚钱。"},{"id":"xianliu","word":"限流","alternatives":["xl","被l了","小黑屋"],"category":"平台限流","reason":"公开抱怨“限流”本身也被视为讨论平台规则的负面内容，博主常用缩写。","example":"上一篇被xl了，重新发一遍","trivia":""},{"id":"hexie","word":"和谐","alternatives":["河蟹","被河蟹","hx"],"category":"政治审查","reason":"“和谐”在网络上指内容被审查删除。为了不让这个词本身被过滤，网友写成同音的“河蟹”。","example":"昨天那条视频已经被河蟹了","trivia":"来自“构建和谐社会”的口号，2007 年前后开始流行。"},{"id":"shantie","word":"删帖","alternatives":["404","被夹了","被吞","炸号"],"category":"政治审查","reason":"说出“删帖”“屏蔽”容易让内容再被删一次，网友改用网页错误码 404 等说法。","example":"评论又被吞了，换个说法再发","trivia":"404 是网页“找不到”的错误码，“被 404”就是被删得找不到了。"},{"id":"xijinping","word":"习近平","alternatives":["xjp","维尼","包子","庆丰帝","刁禁评","习惯了近来平平淡淡的生活"],"category":"政治审查","reason":"国家领导人的名字在各平台受严格过滤，带调侃意味的昵称也会陆续被屏蔽，于是网友不断造新称呼。","example":"（多数平台上这几个称呼本身也已被屏蔽）","trivia":"“刁禁评”：“刁”形似“习”，“禁评”谐音“近平”，又暗指“禁止评论”；“习惯了近来平平淡淡的生活”把“习、近、平”三个字藏在一句普通的话里。2013 年网友把他和奥巴马的合影比作小熊维尼和跳跳虎，2017 年起“维尼”在多个平台被屏蔽。"},{"id":"liusi","word":"六四","alternatives":["五月三十五日","8平方","那年那天"],"category":"政治审查","reason":"1989 年 6 月 4 日的事件在中国内地网络上被全面屏蔽，每年 6 月前后过滤更严。","example":"五月三十五日，有些事不该被忘记","trivia":"8 的平方是 64，所以“8平方”也被拿来指代。"},{"id":"gongchandang","word":"共产党","alternatives":["gcd","tg","党"],"category":"政治审查","reason":"带执政党名称的批评或调侃内容审核很严，网友用拼音缩写代替。","example":"这个政策是gcd哪年提出来的？","trivia":"“tg”是“土共”的拼音缩写，带调侃意味。"},{"id":"zhongguo","word":"中国","alternatives":["种花家","兔子","zg"],"category":"政治审查","reason":"“中国”本身不是禁词，但涉及国家的负面讨论容易被删，网友常用“种花家”“zg”等说法。","example":"zg的外卖真的是全世界最方便的","trivia":"“种花家”“兔子”来自动画《那年那兔那些事儿》。"},{"id":"yuetan","word":"被约谈","alternatives":["喝茶","被请喝茶"],"category":"政治审查","reason":"被警方或国保叫去问话是敏感话题，大家用“喝茶”委婉代替。","example":"他前几天发了条帖子，第二天就被请去喝茶了","trivia":"约谈时对方常说“请你来喝杯茶”，这个说法由此而来。"},{"id":"kangyi","word":"抗议","alternatives":["散步","聚集","ky"],"category":"政治审查","reason":"“抗议”“游行”等词在国内平台会被过滤，网友用中性的日常词语代替。","example":"听说周末好多人去市中心散步了","trivia":"2007 年厦门市民以“集体散步”的方式反对 PX 化工项目。"},{"id":"qiang","word":"枪","alternatives":["木仓","qiang","🔫"],"category":"平台限流","reason":"枪支属于违禁品，相关词会被屏蔽，连游戏、影视讨论也常被误伤，于是把字拆开写。","example":"这把游戏我一木仓爆头！","trivia":"“木仓”就是把“枪”字左右拆开。"},{"id":"sha","word":"杀","alternatives":["鲨","沙","sha"],"category":"平台限流","reason":"“杀”“杀人”等暴力词会触发审核，影视解说和游戏区常用同音字。","example":"这部悬疑片的凶手居然鲨了三个人","trivia":"“鲨”还有一层可爱的意思，所以“鲨了你”听起来没那么凶。"},{"id":"seqing","word":"色情","alternatives":["涩涩","瑟瑟","sq"],"category":"平台限流","reason":"色情内容在国内平台违法，连提到这个词都容易被限流，网友用叠字谐音代替。","example":"这个画风好涩涩，不敢在地铁上看","trivia":""},{"id":"dupin","word":"毒品","alternatives":["du品","dp","叶子"],"category":"平台限流","reason":"毒品属于严格过滤的违法内容，禁毒科普和新闻讨论也会被误伤。","example":"这部缉du片拍得真紧张","trivia":"“叶子”是对大麻的俗称。"},{"id":"diyi","word":"第一","alternatives":["NO.1","top1","di一"],"category":"广告法","reason":"“第一”“首个”“唯一”属于《广告法》禁止的极限用语，商品笔记里出现会被判违规。","example":"这款面霜是我心里的top1","trivia":""},{"id":"yongjiu","word":"永久","alternatives":["长久","持久","yj"],"category":"广告法","reason":"“永久”“万能”“百分百”等绝对化用语属于违规宣传，商家常改成“持久”。","example":"这个睫毛膏是真的持久，一天不晕妆","trivia":""},{"id":"mianfei","word":"免费","alternatives":["0元","白嫖","mf"],"category":"平台限流","reason":"“免费领”“免费送”常被视为营销引流或诱导互动，平台会降低推荐。","example":"评论区抽三位姐妹0元送同款","trivia":""},{"id":"taobao","word":"淘宝","alternatives":["某宝","tb","橙色软件"],"category":"引流/联系方式","reason":"在一个平台上提到别家购物平台会被当作站外导流，小红书、抖音都会限流。","example":"同款在某宝搜关键词就能找到","trivia":""},{"id":"douyin","word":"抖音","alternatives":["某音","dy","斗音"],"category":"引流/联系方式","reason":"竞争平台的名字在各平台互相限流，视频搬运和跨平台引流都会被处理。","example":"这个舞最近在某音很火","trivia":""},{"id":"qq","word":"QQ","alternatives":["扣扣","企鹅","Q"],"category":"引流/联系方式","reason":"QQ 号、QQ 群属于站外联系方式，留号会被删除，网友用“企鹅”“扣扣”代替。","example":"想一起开黑的来企鹅群","trivia":"“企鹅”来自 QQ 的企鹅形象。"},{"id":"dianhua","word":"电话","alternatives":["📱","dh","联系方式见主页"],"category":"引流/联系方式","reason":"直接留手机号属于站外导流，也有隐私风险，平台会屏蔽号码和“电话”字样。","example":"预约方式见主页简介📱","trivia":"有人把数字写成“幺两三”或大写“壹贰叁”，躲开号码识别。"},{"id":"lianjie","word":"链接","alternatives":["lj","🔗","链jie"],"category":"引流/联系方式","reason":"“求链接”“发链接”会被识别为导购导流，笔记和评论容易被限流。","example":"有姐妹求lj，统一放评论区置顶啦","trivia":""},{"id":"zhuanzhang","word":"转账","alternatives":["zz","转z"],"category":"金钱交易","reason":"公开讨论转账、收款容易被判定为私下交易，也常和诈骗内容一起被过滤。","example":"确认收货后再zz哦","trivia":""},{"id":"hongbao","word":"红包","alternatives":["hb","🧧"],"category":"金钱交易","reason":"“发红包”“返现”被视为诱导互动或违规营销，平台会限制这类内容。","example":"好评截图返🧧","trivia":""},{"id":"chushou","word":"出售","alternatives":["出","回血","c"],"category":"金钱交易","reason":"社区平台不允许私下交易，“出售”“转卖”会被限流，闲置交易常写成“回血”。","example":"全新未拆，九折回血","trivia":"“回血”来自游戏里恢复血量，比喻把闲置卖掉挽回一点损失。"},{"id":"daikuan","word":"贷款","alternatives":["dk","带款"],"category":"金钱交易","reason":"金融借贷宣传需要资质，提到“贷款”容易被当作违规金融广告。","example":"买房的dk终于批下来了","trivia":""},{"id":"yao","word":"药","alternatives":["yao","💊","要"],"category":"健康医疗","reason":"没有资质不能宣传药品，提到药名和疗效会被判为违规医疗内容。","example":"感冒了，吃了💊睡一觉好多了","trivia":""},{"id":"yiyu","word":"抑郁","alternatives":["emo","抑yu","yy"],"category":"健康医疗","reason":"心理疾病话题容易触发审核，或被误判为自伤内容，网友常用“emo”等说法。","example":"最近有点emo，出去走走散散心","trivia":"emo 原是一种音乐风格，后来在网络上指情绪低落。"},{"id":"aizheng","word":"癌症","alternatives":["ca","a症","肿瘤"],"category":"健康医疗","reason":"疾病加疗效的说法容易被判为医疗广告，病友交流常用医学缩写。","example":"家里人查出ca，求有经验的朋友分享","trivia":"ca 是医学上对癌（carcinoma）的常用缩写。"},{"id":"zhengrong","word":"整容","alternatives":["医美","zr","变美"],"category":"健康医疗","reason":"医美项目宣传受严格监管，分享“整容”经历容易被当作医疗广告。","example":"做了个小医美项目，恢复期一周","trivia":""}];
